/* Actual navigation shell. Graph links express navigation, not causal claims. */
(()=>{
const css=document.createElement('link');css.rel='stylesheet';css.href='star-map.css';document.head.appendChild(css);
try{if(localStorage.getItem('workbench-theme')==='light')document.documentElement.dataset.theme='light'}catch(e){}
const groups=[
 {p:'position',title:'第一部分　定位',color:'#c86955',items:[['人设定位','persona-module'],['商业定位','offering'],['内容定位','contentAudience']]},
 {p:'topic',title:'第二部分　选题',color:'#75a17e',items:[['给谁看','audience'],['为什么值得看','topic'],['真实材料与表达','material']]},
 {p:'writing',title:'第三部分　文案',color:'#5999c7',items:[['素材挖掘','material',0],['结构方案','outline',1],['口播与配音 Vlog','form',0],['改稿与复查','notes',3]]},
 {p:'shoot',title:'第四部分　准备拍摄',color:'#d7ae57',items:[['Vlog 分镜表','',null,'配音 Vlog'],['口播拍摄清单','',null,'口播']]},
 {p:'review',title:'第五部分　看成片',color:'#a87db7',items:[['内容与结构','reviewNotes'],['段落取舍','passage'],['修改复验','filmCheck']]}
];
let search='';
const aside=document.querySelector('aside');
aside.innerHTML=`<button class="sidebar-close" aria-label="关闭目录">×</button><div class="brand">创作知识库</div><div class="catalog-caption">CONTENT WORKBENCH</div><div class="catalog-search"><label for="catalog-search" class="hidden">搜索目录</label><input id="catalog-search" placeholder="搜索目录与入口" aria-label="搜索目录与入口"><kbd>⌘ K</kbd></div><nav aria-label="工作流程"><div class="catalog-group" data-group="guide"><button class="catalog-heading" data-page="home">导读</button><button class="catalog-sub" data-route="home"><em>0.1</em>知识地图</button><button class="catalog-sub" data-route="home" data-target="start-guide"><em>0.2</em>从想法到作品</button></div>${groups.map((g,i)=>`<div class="catalog-group"><button class="catalog-heading" data-page="${g.p}">${g.title}</button>${g.items.map((t,j)=>`<button class="catalog-sub" data-route="${g.p}" data-target="${t[1]}" ${t[2]!=null?`data-step="${t[2]}"`:''} ${t[3]?`data-form="${t[3]}"`:''}><em>${i+1}.${j+1}</em>${t[0]}</button>`).join('')}</div>`).join('')}<p class="catalog-empty" hidden>没有匹配的目录，可换个词试试。</p></nav><div class="aside-bottom"><button id="theme-toggle">☼ 切换深浅色</button><button data-page="gaps">待补清单</button><p>方法来自知识库 · 当前未实时连接<br>交互原型，AI诊断尚未接入</p></div>`;
const scrim=document.createElement('button');scrim.className='menu-scrim';scrim.setAttribute('aria-label','关闭目录');document.body.appendChild(scrim);
document.querySelector('.topbar').insertAdjacentHTML('afterbegin','<button class="menu-toggle" aria-label="打开目录" aria-expanded="false">☰ 目录</button>');document.querySelector('.badge').textContent='星链版 · 交互原型';
function close(){document.body.classList.remove('menu-open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false')}
scrim.onclick=close;aside.querySelector('.sidebar-close').onclick=close;
document.querySelector('.menu-toggle').onclick=()=>{const open=document.body.classList.toggle('menu-open');document.querySelector('.menu-toggle').setAttribute('aria-expanded',String(open))};
aside.querySelector('#theme-toggle').onclick=()=>{const t=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=t;try{localStorage.setItem('workbench-theme',t)}catch(e){}};
function filter(){let count=0;aside.querySelectorAll('.catalog-group').forEach(g=>{const all=g.querySelector('.catalog-heading').textContent.includes(search);let visible=0;g.querySelectorAll('.catalog-sub').forEach(b=>{b.hidden=!(all||b.textContent.toLowerCase().includes(search));if(!b.hidden)visible++});g.hidden=!visible;count+=visible});aside.querySelector('.catalog-empty').hidden=count>0}
aside.querySelector('#catalog-search').oninput=e=>{search=e.target.value.trim().toLowerCase();filter()};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.body.classList.add('menu-open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','true');aside.querySelector('#catalog-search').focus()}if(e.key==='Escape')close()});
function go(p,target='',s=null,f=null){page=p;if(s!==null)step=Number(s);if(f){state.form=f;save()}render();close();window.scrollTo(0,0);if(target){let el=document.getElementById(target);if(target==='passage')el=[...app.querySelectorAll('h2,h3')].find(x=>x.textContent.includes('段落怎么取舍'));if(target==='filmCheck')el=app.querySelector('[data-table="filmCheck"]');if(el){for(let parent=el.parentElement;parent;parent=parent.parentElement){if(parent.tagName==='DETAILS')parent.open=true}el.scrollIntoView({block:'center'});if(/INPUT|TEXTAREA|SELECT/.test(el.tagName))el.focus({preventScroll:true})}}}
// Deliberately irregular constellation: small topic nodes, no central hub.
const nodes=[
 ['定位',215,145,0,18,''],['社会身份',120,85,0,9,'socialIdentity'],['商业身份',95,180,0,9,'businessIdentity'],['内容定位',175,250,0,10,'contentAudience'],
 ['选题',610,155,1,18,''],['受众',560,55,1,10,'audience'],['观看价值',745,85,1,10,'topic'],['真实材料',830,220,1,10,'material'],
 ['文案',445,310,2,19,''],['素材挖掘',355,210,2,10,'material',0],['结构方案',275,335,2,10,'outline',1],['口播',365,410,2,10,'form',0],['配音 Vlog',530,405,2,10,'form',0],['改稿',645,315,2,10,'draft',2],
 ['准备拍摄',170,460,3,18,''],['分镜表',70,365,3,10,'',null,'配音 Vlog'],['口播清单',70,510,3,10,'',null,'口播'],['景别与视角',210,555,3,9,'shootNotes'],['素材准备',370,525,3,10,'shootNotes'],
 ['看成片',810,415,4,18,''],['段落取舍',885,320,4,10,'passage'],['内容判断',920,460,4,9,'reviewNotes'],['修改复验',820,540,4,10,'filmCheck']
];
function map(){let seed=15;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};let dots=nodes.map(n=>({x:n[1],y:n[2],named:true}));for(let row=0;row<8;row++)for(let col=0;col<11;col++){const x=55+col*82+(rand()-.5)*46,y=45+row*71+(rand()-.5)*40;if(((x-490)/470)**2+((y-300)/290)**2>1.05)continue;if(nodes.some(n=>Math.hypot(x-n[1],y-n[2])<30))continue;dots.push({x,y})}let pairs=new Set();dots.forEach((a,i)=>{dots.map((b,j)=>({j,d:Math.hypot(a.x-b.x,a.y-b.y)})).filter(o=>o.j!==i&&o.d<235).sort((a,b)=>a.d-b.d).slice(0,i<nodes.length?7:5).forEach(({j})=>pairs.add([Math.min(i,j),Math.max(i,j)].join('-')))});return `<svg class="star-svg" viewBox="0 0 1000 610" role="group" aria-label="创作知识地图：点击彩色主题进入对应工具"><g aria-hidden="true">${[...pairs].map(k=>{const [a,b]=k.split('-').map(Number);return `<line class="star-edge" data-a="${a}" data-b="${b}" x1="${dots[a].x}" y1="${dots[a].y}" x2="${dots[b].x}" y2="${dots[b].y}"/>`}).join('')}${dots.slice(nodes.length).map(d=>`<circle class="star-dot" cx="${d.x}" cy="${d.y}" r="3"/>`).join('')}</g>${nodes.map((n,i)=>`<g class="star-node ${n[4]>15?'major':''}" tabindex="0" role="link" aria-label="${n[0]}，进入${names[groups[n[3]].p]}" data-node="${i}"><title>${n[0]} · 点击进入</title><circle cx="${n[1]}" cy="${n[2]}" r="${n[4]}" fill="${groups[n[3]].color}"/><text x="${n[1]+n[4]+10}" y="${n[2]+5}" ${n[1]>865?'text-anchor="end" transform="translate(-40,-22)"':''}>${n[0]}</text></g>`).join('')}</svg>`}
function home(){app.innerHTML=`<section class="map-hero"><div class="eyebrow">从定位到成片 / 一条清楚的创作路径</div><h1>创作知识库</h1><p>从定位、选题到写稿、拍摄与审片。<br>沿着目录查方法，也可以从当前任务直接开始。</p></section><section class="star-panel"><div class="star-heading"><h2>知识地图</h2><span>悬停查看关联 · 点击进入</span></div><div class="star-scroll">${map()}</div><div class="star-legend">${groups.map(g=>`<button data-route="${g.p}"><i style="background:${g.color}"></i>${names[g.p]}</button>`).join('')}</div><p class="map-note">按五个任务入口组织的导航示意；连线不代表课程因果结论，灰点仅辅助构图。手机可横向滑动地图。</p></section><section class="map-bottom" id="start-guide"><div><h3>从你已有的材料开始</h3><p>有介绍，去定位；有想法，去选题；有稿件，去文案；有视频，去看成片。</p></div><button class="primary" data-route="position" data-target="persona-module">试用人设定位 →</button></section><details class="source"><summary>这版能做什么？</summary><p>填写与保存材料、查看方法提示与预写示例、导出记录、本地播放视频。AI自动诊断、自动写稿及实时知识库检索尚未接入。知识地图是工具导航，不是课程全文。</p></details>`;app.querySelectorAll('[data-node]').forEach(el=>{const index=Number(el.dataset.node),n=nodes[index];const select=()=>go(groups[n[3]].p,n[5],n[6]??null,n[7]||null);el.onclick=select;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}};const highlight=on=>app.querySelectorAll('.star-edge').forEach(l=>l.classList.toggle('on',on&&(Number(l.dataset.a)===index||Number(l.dataset.b)===index)));el.onmouseenter=()=>highlight(true);el.onmouseleave=()=>highlight(false);el.onfocus=()=>highlight(true);el.onblur=()=>highlight(false)})}
const previous=render;render=function(){previous();if(page==='home')home();document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route,b.dataset.target||'',b.dataset.step??null,b.dataset.form||null));aside.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));filter()};render();
})();
